func mAnd(ps *ParserState, pos Pos, fns ...MFn) (MPos, error) {
	p0 := pos
	for _, fn := range fns {
		if mp, err := fn(ps, pos); err != nil {
			return mp, err
		} else {
			pos = mp.End
		}
	}
	return MPos{p0, pos}, nil
}
func mOr(ps *ParserState, pos Pos, fns ...MFn) (MPos, error) {
	for _, fn := range fns {
		if mp, err := fn(ps, pos); err != nil {
			if IsFatalError(err) {
				return mp, err
			}
		} else {
			return mp, nil
		}
	}
	return MPos{pos, pos}, NoMatchErr
}

